<?php
if(!$u){echo '<a href="'.$nu('/community/account/').'">'.$n('login').'</a>';return;}
$kind=(string)($_GET['kind']??$_POST['kind']??'');$id=(string)($_GET['id']??$_POST['target']??'');
try{networkOwnTarget($u,$kind,$id);}catch(DomainException $e){networkUnavailable();return;}
$language=(string)($_GET['edition']??siteLanguage());if(!isset(networkContentLanguages()[$language]))$language=siteLanguage();$current=networkLocale($kind,$id,$language);$doc=$current?json_decode($current['document'],true):[];
$pending=socialQuery("SELECT document FROM network_submissions WHERE owner=? AND kind=? AND target=? AND language=? AND state='pending' ORDER BY created DESC LIMIT 1",[$u['id'],$kind,$id,$language])->fetchColumn();if($pending)$doc=json_decode($pending,true);
if(!$doc){$ownLocale=socialQuery("SELECT document FROM network_localizations WHERE kind=? AND target=? AND language=? AND state='pending'",[$kind,$id,$language])->fetchColumn();if($ownLocale)$doc=json_decode($ownLocale,true);}
?>
<h1><?=$n('translations')?></h1><?php if(!$doc):?><p role="status"><?=$n('new_translation')?></p><?php endif?><p><?=$n('language_notice')?></p><nav class="network-tabs network-language-tabs"><?php foreach(networkContentLanguages() as $code=>$label):?><a href="<?=$nu('/community/translations/')?>&amp;kind=<?=e($kind)?>&amp;id=<?=e($id)?>&amp;edition=<?=e($code)?>" <?=$language===$code?'aria-current="page"':''?>><?=e($label)?></a><?php endforeach?></nav>
<form method="post" class="network-card network-form"><?=csrf()?><input type="hidden" name="network_action" value="translation"><input type="hidden" name="kind" value="<?=e($kind)?>"><input type="hidden" name="target" value="<?=e($id)?>"><input type="hidden" name="content_language" value="<?=e($language)?>"><input type="hidden" name="base_version" value="<?=(int)($current['source_version']??0)?>"><strong><?=e(networkContentLanguages()[$language])?></strong><label><?=$n('title')?><input name="title" value="<?=e($doc[$kind==='trip'?'public_title':'title']??'')?>" required minlength="3" maxlength="160" lang="<?=e($language)?>" dir="auto"></label><label><?=$n('body')?><textarea name="body" required minlength="20" maxlength="12000" rows="8" lang="<?=e($language)?>" dir="auto"><?=e($doc[$kind==='post'?'body':($kind==='trip'?'summary':'description')]??'')?></textarea></label><?php if($kind==='place')foreach(['address','hours','price'] as $key):?><label><?=e(socialT($key))?><textarea name="<?=e($key)?>" maxlength="1000" lang="<?=e($language)?>" dir="auto"><?=e($doc[$key]??'')?></textarea></label><?php endforeach?><p><?=cmAutoEnabled()?e(crT('approved')):$n('pending_notice')?></p><button class="button"><?=$n('submit')?></button></form>
<?php foreach(socialQuery('SELECT language,state,note FROM network_submissions WHERE owner=? AND kind=? AND target=? ORDER BY created DESC LIMIT 20',[$u['id'],$kind,$id]) as $review):?><p><?=e($review['language'])?> · <?=e(socialT($review['state']))?> <?=e($review['note'])?></p><?php endforeach?>

<?php if($current):?><form method="post" class="network-card"><?=csrf()?><input type="hidden" name="network_action" value="withdraw_language"><input type="hidden" name="kind" value="<?=e($kind)?>"><input type="hidden" name="target" value="<?=e($id)?>"><input type="hidden" name="content_language" value="<?=e($language)?>"><button class="button secondary"><?=$n('withdraw_language')?></button></form><?php endif?>
